CREATE TABLE IF NOT EXISTS microredes (id INT PRIMARY KEY AUTO_INCREMENT, nombre VARCHAR(150) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS establecimientos (id INT PRIMARY KEY AUTO_INCREMENT, codigo VARCHAR(30) NOT NULL UNIQUE, nombre VARCHAR(180) NOT NULL, microred_id INT NOT NULL, cod_distrito VARCHAR(30) NOT NULL, distrito VARCHAR(150) NOT NULL, categoria VARCHAR(30) NOT NULL, FOREIGN KEY (microred_id) REFERENCES microredes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS usuarios (id INT PRIMARY KEY AUTO_INCREMENT, nombre VARCHAR(150) NOT NULL, usuario VARCHAR(80) NOT NULL UNIQUE, clave VARCHAR(255) NOT NULL, rol ENUM('admin','tecnico','microred','establecimiento') NOT NULL, microred_id INT NULL, establecimiento_id INT NULL UNIQUE, activo TINYINT NOT NULL DEFAULT 1, intentos INT NOT NULL DEFAULT 0, bloqueo_hasta DATETIME NULL, FOREIGN KEY (microred_id) REFERENCES microredes(id), FOREIGN KEY (establecimiento_id) REFERENCES establecimientos(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS productos (id INT PRIMARY KEY AUTO_INCREMENT, codigo VARCHAR(30) NOT NULL UNIQUE, nombre VARCHAR(255) NOT NULL, tipo VARCHAR(20) NOT NULL, unidad VARCHAR(60) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS instalacion (id INT PRIMARY KEY, fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS imi_apertura (establecimiento_id INT NOT NULL, producto_id INT NOT NULL, saldo BIGINT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY(establecimiento_id,producto_id), FOREIGN KEY(establecimiento_id) REFERENCES establecimientos(id), FOREIGN KEY(producto_id) REFERENCES productos(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS imi_reportes (id INT PRIMARY KEY AUTO_INCREMENT, establecimiento_id INT NOT NULL, periodo DATE NOT NULL, estado ENUM('borrador','enviado') NOT NULL DEFAULT 'borrador', version INT NOT NULL DEFAULT 1, actualizado_por INT NULL, actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY unico_mes(establecimiento_id,periodo), FOREIGN KEY(establecimiento_id) REFERENCES establecimientos(id), FOREIGN KEY(actualizado_por) REFERENCES usuarios(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS imi_detalles (reporte_id INT NOT NULL, producto_id INT NOT NULL, stock_segun BIGINT UNSIGNED NOT NULL, recibido BIGINT UNSIGNED NOT NULL, consumo BIGINT UNSIGNED NOT NULL, ajuste BIGINT UNSIGNED NOT NULL, stock_inicial BIGINT UNSIGNED NOT NULL, stock_final BIGINT UNSIGNED NOT NULL, PRIMARY KEY(reporte_id,producto_id), FOREIGN KEY(reporte_id) REFERENCES imi_reportes(id) ON DELETE CASCADE, FOREIGN KEY(producto_id) REFERENCES productos(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS imi_periodos (periodo DATE PRIMARY KEY, estado ENUM('abierto','cerrado') NOT NULL DEFAULT 'cerrado', inicio DATETIME NULL, fin DATETIME NULL, version INT NOT NULL DEFAULT 1, actualizado_por INT NULL, actualizado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(actualizado_por) REFERENCES usuarios(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
